uniform sampler2D cc_spriteTexture;
float curveDistance (vec2 p, vec4 a, vec4 b) {
  vec2 lower = min(min(a.xy,a.zw),min(b.xy,b.zw))-vec2(jointMeta.y+jointMeta.w+2.0);
  vec2 upper = max(max(a.xy,a.zw),max(b.xy,b.zw))+vec2(jointMeta.y+jointMeta.w+2.0);
  if (any(lessThan(p,lower)) || any(greaterThan(p,upper))) return 10000.0;
  vec2 previous = a.xy;
  float nearest = 10000.0;
  for (int i = 1; i <= 8; i++) {
    float t = float(i) / 8.0, v = 1.0 - t;
    vec2 next = v*v*v*a.xy + 3.0*v*v*t*a.zw + 3.0*v*t*t*b.xy + t*t*t*b.zw;
    vec2 edge = next - previous;
    float u = clamp(dot(p - previous, edge) / max(.0001, dot(edge, edge)), 0.0, 1.0);
    float along = (float(i - 1) + u) / 8.0;
    float width = mix(jointMeta.y, jointMeta.z, smoothstep(0.0, 1.0, along));
    nearest = min(nearest, length(p - previous - edge*u) - width);
    previous = next;
  }
  return nearest;
}
float mountingDistance (vec2 p) {
  float d = 10000.0;
  if (jointMeta.x > .5) d = min(d, curveDistance(p, joint0A, joint0B));
  if (jointMeta.x > 1.5) d = min(d, curveDistance(p, joint1A, joint1B));
  if (jointMeta.x > 2.5) d = min(d, curveDistance(p, joint2A, joint2B));
  if (jointMeta.x > 3.5) d = min(d, curveDistance(p, joint3A, joint3B));
  return d;
}
float roundedUnion (float a, float b) {
  float k = jointMeta.w;
  float h = clamp(.5 + .5*(b-a)/k, 0.0, 1.0);
  return mix(b, a, h) - k*h*(1.0-h);
}
float mountingAlpha (vec2 uv, float original) {
  if (jointMeta.x < .5) return original;
  vec2 p = vec2(uv.x-.5, .5-uv.y) / jointUnits.xy;
  float d = mountingDistance(p);
  if (gapParams.w > 0.0) {
    vec2 cap = vec2(.809016994, .587785252)*gapParams.z;
    float ring = abs(length(p)-gapParams.z);
    if (p.y > abs(p.x)*.726542528) ring = min(length(p-cap), length(p-vec2(-cap.x,cap.y)));
