  vec2 end = vec2(.809016994, .587785252) * gapParams.z;
  float distanceToStroke = abs(length(p) - gapParams.z);
  if (p.y > abs(p.x) * .726542528)
    distanceToStroke = min(length(p - end), length(p - vec2(-end.x, end.y)));
  return 1.0 - smoothstep(gapParams.w - .65, gapParams.w + .65, distanceToStroke);
}
float qGapMask (vec2 uv) {
  if (qGapParams.w < .5) return 1.0;
  vec2 p = vec2(uv.x - .5, .5 - uv.y) / gapParams.xy;
  vec2 tip = qGapParams.xy;
  if (p.x >= 0.0 || p.y <= 0.0 || p.x * tip.y - p.y * tip.x <= 0.0) return 1.0;
  return 1.0 - smoothstep(qGapParams.z - .65, qGapParams.z + .65, length(p - tip));
}
float silhouette (vec2 uv) {
  vec2 inside = step(vec2(0.0), uv) * step(uv, vec2(1.0));
  float a = CCSampleWithAlphaSeparated(cc_spriteTexture, clamp(uv, vec2(0.0), vec2(1.0))).a * gapMask(uv) * qGapMask(uv);
  return mountingAlpha(uv, a) * inside.x * inside.y;
}
vec4 frag () {
  vec2 uv = (uv0 - 0.5) * shadowParams.xy + 0.5;
  vec2 d = shadowParams.zw;
  if (outlineParams.x > .5) {
    float outlineAlpha = silhouette(uv);
    for (int i = 0; i < 16; i++) {
      float angle = float(i) * 0.392699082;
      outlineAlpha = max(outlineAlpha, silhouette(uv + vec2(cos(angle), sin(angle)) * d));
    }
    return vec4(color.rgb, outlineAlpha * color.a);
  }
  float a = silhouette(uv) * 0.20;
  a += (silhouette(uv + vec2(d.x, 0.0)) + silhouette(uv - vec2(d.x, 0.0))
      + silhouette(uv + vec2(0.0, d.y)) + silhouette(uv - vec2(0.0, d.y))) * 0.10;
  a += (silhouette(uv + d) + silhouette(uv - d)
      + silhouette(uv + vec2(d.x, -d.y)) + silhouette(uv + vec2(-d.x, d.y))) * 0.075;
  a += (silhouette(uv + vec2(2.0 * d.x, 0.0)) + silhouette(uv - vec2(2.0 * d.x, 0.0))
      + silhouette(uv + vec2(0.0, 2.0 * d.y)) + silhouette(uv - vec2(0.0, 2.0 * d.y))) * 0.025;
  vec3 tint = color.rgb;
  if (glowParams.y > 0.5) {
    float blurred = 0.0;
    float weightSum = 0.0;
    for (int x = -4; x <= 4; x++) {
      for (int y = -4; y <= 4; y++) {
        vec2 offset = vec2(float(x), float(y));
        float weight = exp(-dot(offset, offset) / 5.12);
        blurred += silhouette(uv + offset * d * 0.375) * weight;
        weightSum += weight;
      }
    }
    a = blurred / weightSum;
    vec2 centered = uv - 0.5 + vec2(0.00001);
    float hue = fract((atan(centered.y, centered.x) / 6.2831853 + 0.5) * 3.0 + glowParams.z);
    vec3 spectrum = clamp(abs(fract(hue + vec3(0.0, 0.6666667, 0.3333333)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
    tint = mix(vec3(1.0), spectrum, 0.90);
    tint = mix(tint, vec3(1.0), smoothstep(0.08, 0.48, a) * 0.38);
  }
  return vec4(tint, min(1.0, color.a * a * glowParams.x));
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

